def update_recovery_state(state, voltage_v, recovery_threshold_v, required_good_samples):
    """Clear a latched fault after enough consecutive healthy voltage samples."""
    if not state["fault_active"]:
        return False

    if voltage_v < recovery_threshold_v:
        state["good_samples"] = 0
        return False

    state["good_samples"] += 1
    if state["good_samples"] >= required_good_samples:
        state["fault_active"] = False
        state["good_samples"] = 0
        return True

    return False
